const USER_COOKIE = 'user_auth';
const ROLES = Object.keys(roleData) as RoleKey[];

function escapeHtml(value: unknown): string {
  return String(value ?? '').replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;').replaceAll("'", '&#39;');
}

function normalizeUploadFileName(value: string): string {
  const decoded=Buffer.from(value,'latin1').toString('utf8');
  return decoded.includes('\uFFFD')?value:decoded;
}

async function sendRequestMail(to:string,subject:string,text:string,html:string):Promise<void>{
  if(!process.env.SMTP_HOST){console.log(`[개발용 메일] 수신: ${to}\n제목: ${subject}\n${text}`);return}
  const port=Number(process.env.SMTP_PORT??587),fromAddress=process.env.SMTP_FROM||process.env.SMTP_USER;
  const transporter=nodemailer.createTransport({host:process.env.SMTP_HOST,port,secure:process.env.SMTP_SECURE?process.env.SMTP_SECURE==='true':port===465,auth:process.env.SMTP_USER?{user:process.env.SMTP_USER,pass:process.env.SMTP_PASS??process.env.SMTP_PASSWORD??''}:undefined});
  const from=process.env.SMTP_FROM_NAME&&fromAddress?{name:process.env.SMTP_FROM_NAME,address:fromAddress}:fromAddress;
  await transporter.sendMail({from,to,subject,text,html});
}

