function settingsSuccessMessageScript(): string {
  return String.raw`document.addEventListener('DOMContentLoaded',()=>{const form=document.getElementById('settingsForm'),settingsModal=document.getElementById('userSettingsModal'),confirmButton=document.querySelector('[data-confirm=yes]'),confirmOverlay=confirmButton?.closest('div[style*="position:fixed"]'),message=document.getElementById('settingsMessage');if(!form||!confirmButton||!confirmOverlay)return;const success=document.createElement('div');success.style.cssText='display:none;position:fixed;inset:0;z-index:180;align-items:center;justify-content:center;padding:20px;background:rgba(15,29,50,.62)';success.innerHTML='<div style="width:min(380px,100%);overflow:hidden;border-radius:14px;background:#fff;color:#172033;box-shadow:0 24px 70px rgba(0,0,0,.28)"><h3 style="margin:0;padding:16px;text-align:center;background:#172033;color:#fff;font-size:1rem">사용자 정보 수정</h3><p style="margin:0;padding:26px;text-align:center;line-height:1.6">사용자 정보가 수정되었습니다.</p><div style="display:flex;justify-content:center;padding:0 20px 20px"><button type="button" style="min-width:90px;padding:10px 18px;border:0;border-radius:8px;background:#2563eb;color:#fff;font-weight:800;cursor:pointer">확인</button></div></div>';document.body.append(success);success.querySelector('button').onclick=()=>location.reload();confirmButton.onclick=async()=>{confirmOverlay.style.display='none';message.textContent='';const payload=Object.fromEntries(new FormData(form));const response=await fetch('/app/api/profile',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}),result=await response.json();if(!response.ok){message.textContent=result.message||'저장하지 못했습니다.';settingsModal.style.display='flex';return}settingsModal.style.display='none';success.style.display='flex'}});`;
}

function settingsDirtyStateScript(): string {
  return String.raw`document.addEventListener('DOMContentLoaded',()=>{const form=document.getElementById('settingsForm'),openButton=document.getElementById('userSettingsButton');if(!form||!openButton)return;const saveButton=form.querySelector('button[type=submit]');let initial='';function snapshot(){return JSON.stringify(Array.from(new FormData(form).entries()))}function update(){const changed=initial!==''&&snapshot()!==initial;saveButton.disabled=!changed;saveButton.style.opacity=changed?'1':'.45';saveButton.style.cursor=changed?'pointer':'not-allowed'}const originalOpen=openButton.onclick;openButton.onclick=async event=>{await originalOpen.call(openButton,event);initial=snapshot();update()};form.addEventListener('input',update);form.addEventListener('change',update);saveButton.disabled=true;saveButton.style.opacity='.45';saveButton.style.cursor='not-allowed'});`;
}

function settingsAlertReplacementScript(): string {
  return String.raw`document.addEventListener('DOMContentLoaded',()=>{document.addEventListener('click',async event=>{const button=event.target.closest?.('[data-confirm=yes]');if(!button)return;event.preventDefault();event.stopImmediatePropagation();const form=document.getElementById('settingsForm'),message=document.getElementById('settingsMessage'),settingsModal=document.getElementById('userSettingsModal'),confirmOverlay=button.parentElement?.parentElement?.parentElement;if(confirmOverlay)confirmOverlay.style.display='none';message.textContent='';button.disabled=true;try{const response=await fetch('/app/api/profile',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(form)))}),result=await response.json();if(!response.ok){message.textContent=result.message||'저장하지 못했습니다.';settingsModal.style.display='flex';return}settingsModal.style.display='none';let saved=document.getElementById('settingsSavedModal');if(!saved){saved=document.createElement('div');saved.id='settingsSavedModal';saved.style.cssText='display:none;position:fixed;inset:0;z-index:200;align-items:center;justify-content:center;padding:20px;background:rgba(15,29,50,.62)';saved.innerHTML='<div style="width:min(380px,100%);overflow:hidden;border-radius:14px;background:#fff;color:#172033;box-shadow:0 24px 70px rgba(0,0,0,.28)"><h3 style="margin:0;padding:16px;text-align:center;background:#172033;color:#fff;font-size:1rem">사용자 정보 수정</h3><p style="margin:0;padding:26px;text-align:center;line-height:1.6">사용자 정보가 수정되었습니다.</p><div style="display:flex;justify-content:center;padding:0 20px 20px"><button type="button" style="min-width:90px;padding:10px 18px;border:0;border-radius:8px;background:#2563eb;color:#fff;font-weight:800;cursor:pointer">확인</button></div></div>';saved.querySelector('button').onclick=()=>location.reload();document.body.append(saved)}saved.style.display='flex'}catch(_error){message.textContent='사용자 정보를 저장하지 못했습니다.';settingsModal.style.display='flex'}finally{button.disabled=false}},true)});`;
}

function attendeeTagInputScript(): string {
  return String.raw`document.addEventListener('DOMContentLoaded',()=>{const original=document.querySelector('#newRequestForm input[name="attendees"]');if(!original)return;const hidden=document.createElement('input');hidden.type='hidden';hidden.name='attendees';const wrap=document.createElement('div');wrap.style.cssText='display:flex;min-height:42px;flex-wrap:wrap;align-items:center;gap:6px;width:100%;padding:6px 10px;border:1px solid #d5dde8;border-radius:8px;background:#fff';const input=document.createElement('input');input.type='text';input.inputMode='text';input.autocomplete='off';input.placeholder=original.placeholder||'이름 입력 후 스페이스';input.style.cssText='flex:1;min-width:150px;min-height:28px!important;padding:2px!important;border:0!important;outline:0;box-shadow:none!important';const tags=[];function sync(){hidden.value=tags.join(', ')}function render(){wrap.querySelectorAll('[data-attendee-tag]').forEach(x=>x.remove());tags.forEach((name,index)=>{const tag=document.createElement('span');tag.dataset.attendeeTag=String(index);tag.style.cssText='display:inline-flex;align-items:center;gap:5px;padding:5px 8px;border-radius:999px;background:#eaf1ff;color:#2855b8;font-size:.76rem;font-weight:800';tag.append(document.createTextNode(name));const remove=document.createElement('button');remove.type='button';remove.setAttribute('aria-label',name+' 삭제');remove.textContent='×';remove.style.cssText='border:0;background:transparent;color:inherit;padding:0;cursor:pointer;font-size:15px;line-height:1';remove.onclick=()=>{tags.splice(index,1);sync();render();input.focus()};tag.append(remove);wrap.insertBefore(tag,input)});sync()}function addValues(raw){raw.split(/[\s,]+/).map(x=>x.trim()).filter(Boolean).forEach(value=>{if(!tags.includes(value))tags.push(value)});input.value='';render()}input.addEventListener('keydown',event=>{if((event.key===' '||event.key==='Enter'||event.key===',')&&input.value.trim()){event.preventDefault();addValues(input.value)}else if(event.key==='Backspace'&&!input.value&&tags.length){tags.pop();render()}});input.addEventListener('blur',()=>{if(input.value.trim())addValues(input.value)});input.addEventListener('paste',event=>{const text=event.clipboardData?.getData('text')||'';if(/[\s,]/.test(text)){event.preventDefault();addValues(text)}});wrap.onclick=()=>input.focus();wrap.append(input);original.replaceWith(wrap);wrap.after(hidden)});`;
}

function requestFileUploadScript(): string {
  return String.raw`document.addEventListener('DOMContentLoaded',()=>{const form=document.getElementById('newRequestForm'),input=document.getElementById('requestFiles'),dropZone=input?.closest('.upload-box'),message=document.getElementById('requestMessage');if(!form||!input||!dropZone)return;const list=document.createElement('div');list.style.cssText='width:100%;margin-top:8px;color:#3555a5;font-size:.72rem;line-height:1.6';dropZone.append(list);function validate(files){const allowed=/\.(pdf|hwp|hwpx|doc|docx|xls|xlsx)$/i,total=files.reduce((sum,file)=>sum+file.size,0);if(files.length>10)return'첨부파일은 최대 10개까지 등록할 수 있습니다.';if(total>50*1024*1024)return'첨부파일 전체 용량은 50MB 이하여야 합니다.';if(files.some(file=>!allowed.test(file.name)))return'PDF, HWP, DOC, XLS 형식만 첨부할 수 있습니다.';return''}function showFiles(){const files=Array.from(input.files||[]),error=validate(files);message.textContent=error;list.textContent=files.length?files.map(file=>file.name+' ('+Math.max(1,Math.ceil(file.size/1024))+'KB)').join(' · '):'';dropZone.style.borderColor=error?'#d92d20':files.length?'#3b82f6':'#d5dde8'}input.addEventListener('change',showFiles);['dragenter','dragover'].forEach(type=>dropZone.addEventListener(type,event=>{event.preventDefault();event.stopPropagation();dropZone.style.background='#eef4ff';dropZone.style.borderColor='#3b82f6'}));['dragleave','drop'].forEach(type=>dropZone.addEventListener(type,event=>{event.preventDefault();event.stopPropagation();dropZone.style.background='#fafbfd'}));dropZone.addEventListener('drop',event=>{const files=Array.from(event.dataTransfer?.files||[]);const error=validate(files);if(error){message.textContent=error;dropZone.style.borderColor='#d92d20';return}const transfer=new DataTransfer();files.forEach(file=>transfer.items.add(file));input.files=transfer.files;showFiles()});form.addEventListener('submit',async event=>{event.preventDefault();event.stopImmediatePropagation();const files=Array.from(input.files||[]),error=validate(files);if(error){message.textContent=error;return}message.textContent='저장 중입니다.';const payload=new FormData(form);payload.set('status',event.submitter?.dataset.status==='draft'?'draft':'submitted');try{const response=await fetch('/app/api/requests/upload',{method:'POST',body:payload}),result=await response.json();if(!response.ok){message.textContent=result.message||'요청을 저장하지 못했습니다.';return}location.reload()}catch(_error){message.textContent='파일 업로드 중 오류가 발생했습니다.'}},true)});`;
}

