function requestAttachmentDetailScript(): string {
  return String.raw`document.addEventListener('DOMContentLoaded',()=>{if(typeof requests==='undefined'||typeof showDetail!=='function')return;const original=showDetail;showDetail=id=>{original(id);const request=requests.find(item=>item.id===id);if(!request?.attachments?.length)return;const section=document.createElement('div');section.style.cssText='margin-top:18px;padding-top:15px;border-top:1px solid #e1e7ef';const title=document.createElement('b');title.textContent='첨부파일';title.style.cssText='display:block;margin-bottom:9px;font-size:.8rem;color:#59677d';section.append(title);request.attachments.forEach(file=>{const link=document.createElement('a');link.href='/app/api/request-attachments/'+file.id+'/download';link.style.cssText='display:flex;align-items:center;justify-content:space-between;gap:10px;margin-top:7px;padding:9px 10px;border:1px solid #d8e1ec;border-radius:8px;color:#2855b8;text-decoration:none;font-size:.78rem';const name=document.createElement('span');name.textContent='📎 '+file.originalName;const size=document.createElement('small');size.textContent=file.fileSize>=1048576?(file.fileSize/1048576).toFixed(1)+'MB':Math.max(1,Math.ceil(file.fileSize/1024))+'KB';link.append(name,size);section.append(link)});detailPanel.append(section)}});`;
}

function requestEditByStatusScript(): string {
  return String.raw`document.addEventListener('DOMContentLoaded',()=>{if(typeof requests==='undefined'||typeof showDetail!=='function')return;const form=document.getElementById('newRequestForm'),editable=new Set(['draft','submitted','revision_requested']),original=showDetail;function openEdit(request){let requestId=form.querySelector('input[name=requestId]');if(!requestId){requestId=document.createElement('input');requestId.type='hidden';requestId.name='requestId';form.append(requestId)}requestId.value=String(request.id);form.elements.requestType.value=request.requestType||'대면보고';form.elements.reportTarget.value=request.reportTarget||'구청장';form.elements.title.value=request.title||'';form.elements.summary.value=request.summary||'';document.getElementById('summaryCount').textContent=(request.summary||'').length+'/500자';const urgency=form.querySelector('input[name=urgency][value="'+(request.urgency||'보통')+'"]');if(urgency)urgency.checked=true;form.elements.desiredDate.value=request.desiredDate||'';const attendeeText=Array.from(form.querySelectorAll('input[type=text]')).find(input=>input.closest('div[style*="flex-wrap"]'));if(attendeeText&&request.attendees){attendeeText.value=request.attendees.replace(/,/g,' ');attendeeText.dispatchEvent(new Event('blur'))}const draftButton=form.querySelector('button[data-status="draft"]');draftButton.disabled=request.status!=='draft';draftButton.style.display=request.status==='draft'?'':'none';requestModal.classList.add('open');form.elements.title.focus()}showDetail=id=>{original(id);const request=requests.find(item=>item.id===id);if(!request)return;Array.from(detailPanel.querySelectorAll('button')).filter(button=>button.textContent==='계속하기').forEach(button=>button.parentElement.remove());const actions=document.createElement('div');actions.style.cssText='display:flex;justify-content:center;padding:18px 0';const button=document.createElement('button');button.type='button';button.textContent='수정';button.disabled=!editable.has(request.status);button.title=button.disabled?'결재선의 다음 단계에서 확인되어 수정할 수 없습니다.':'요청 내용을 수정합니다.';button.style.cssText='border:0;border-radius:9px;padding:10px 24px;background:'+(button.disabled?'#cbd3df':'#2563eb')+';color:#fff;font-weight:900;cursor:'+(button.disabled?'not-allowed':'pointer');button.onclick=()=>openEdit(request);actions.append(button);detailPanel.append(actions)}});`;
}

