function managerWorkspaceScript(): string {
  return String.raw`document.addEventListener('DOMContentLoaded',async()=>{if(typeof role==='undefined'||role!=='manager')return;const content=document.querySelector('.content'),sidebarNav=document.getElementById('nav');if(!content)return;sidebarNav.innerHTML='<button class="active">📁 부서 요청 목록</button><button>📊 부서 현황</button>';const response=await fetch('/app/api/manager/requests');if(!response.ok)return;const data=await response.json(),items=data.requests;content.style.maxWidth='none';content.innerHTML='<section style="display:grid;grid-template-columns:minmax(0,1fr) 330px;gap:18px"><div><div style="margin-bottom:16px"><h2 style="margin:0;font-size:1.25rem">부서 요청 목록</h2><p style="margin:5px 0 0;color:#8792a3;font-size:.78rem">'+new Date().toLocaleString('ko-KR')+'</p></div><div id="managerStats" style="display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-bottom:14px"></div><div style="overflow:hidden;border:1px solid #e1e7ef;border-radius:12px;background:#fff"><h3 style="margin:0;padding:15px;border-bottom:1px solid #edf1f5;font-size:.9rem">부서 요청 목록</h3><div id="managerList"></div></div></div><aside id="managerDetail" style="min-height:520px;padding:20px;border:1px solid #e1e7ef;border-radius:12px;background:#fff;color:#718096;display:grid;place-items:center;text-align:center">📋<br>안건을 클릭하면<br>상세 내용이 표시됩니다.</aside></section>';const groups=[['검토 대기',items.filter(x=>x.status==='submitted').length],['검토 중',items.filter(x=>x.status==='revision_requested').length],['비서실 이관',items.filter(x=>x.status==='secretary_review').length]];managerStats.innerHTML=groups.map(x=>'<div style="padding:17px;background:#fff;border:1px solid #e1e7ef;border-radius:12px"><b style="display:block;color:#4f46e5;font-size:.75rem">'+x[0]+'</b><strong style="display:block;margin-top:7px;font-size:1.5rem">'+x[1]+'</strong></div>').join('');managerList.innerHTML=items.length?items.map(x=>'<button data-manager-id="'+x.id+'" style="display:block;width:100%;padding:15px;border:0;border-bottom:1px solid #edf1f5;background:#fff;text-align:left;cursor:pointer"><span style="float:right;padding:4px 8px;border-radius:999px;background:#eef2ff;color:#4f46e5;font-size:.7rem">'+x.statusLabel+'</span><div style="display:flex;gap:8px;color:#7b8798;font-size:.72rem"><b style="color:#3555d6">'+x.urgency+'</b><span>'+x.requestCode+'</span><span>'+x.requesterName+'</span></div><strong style="display:block;margin-top:7px;font-size:.88rem">'+x.title+'</strong><p style="margin:6px 0;color:#66758b;font-size:.76rem">'+x.summary+'</p><small style="color:#98a2b3">'+x.reportTarget+' · 기한: '+(x.desiredDate||'-')+'</small></button>').join(''):'<div style="padding:30px;text-align:center;color:#98a2b3">접수된 요청이 없습니다.</div>';managerList.querySelectorAll('[data-manager-id]').forEach(button=>button.onclick=()=>{const x=items.find(item=>String(item.id)===button.dataset.managerId);managerDetail.style.display='block';managerDetail.style.color='#172033';managerDetail.innerHTML='<h3 style="margin:0 0 18px">요청 상세</h3>'+[['요청번호',x.requestCode],['상태',x.statusLabel],['요청자',x.requesterName],['긴급도',x.urgency],['보고 대상',x.reportTarget],['안건명',x.title],['안건 요약',x.summary],['의사결정 기한',x.desiredDate||'-']].map(row=>'<div style="padding:10px 0;border-bottom:1px solid #edf1f5"><b style="display:block;margin-bottom:4px;color:#7b8798;font-size:.72rem">'+row[0]+'</b><span style="font-size:.84rem;white-space:pre-wrap">'+row[1]+'</span></div>').join('')})});`;
}

function managerDecisionWorkflowScript(): string {
  return String.raw`document.addEventListener('DOMContentLoaded',()=>{if(typeof role==='undefined'||role!=='manager')return;function dialog(title,body,onConfirm,needsReason=false){const overlay=document.createElement('div');overlay.style.cssText='position:fixed;inset:0;z-index:220;display:flex;align-items:center;justify-content:center;padding:20px;background:rgba(15,29,50,.68)';overlay.innerHTML='<div style="width:min(420px,100%);overflow:hidden;border-radius:14px;background:#fff;color:#172033"><h3 style="margin:0;padding:16px;text-align:center;background:#172033;color:#fff;font-size:1rem"></h3><div style="padding:22px"><p style="margin:0 0 14px;text-align:center;line-height:1.6"></p>'+(needsReason?'<textarea maxlength="1000" placeholder="반려 사유를 입력해 주세요." style="width:100%;min-height:110px;padding:10px;border:1px solid #ccd7e4;border-radius:8px;resize:vertical"></textarea>':'')+'<div data-error style="min-height:20px;margin-top:7px;color:#b42318;font-size:.78rem"></div><div style="display:flex;justify-content:center;gap:8px"><button data-cancel type="button">취소</button><button data-ok type="button">확인</button></div></div></div>';overlay.querySelector('h3').textContent=title;overlay.querySelector('p').textContent=body;overlay.querySelectorAll('button').forEach(button=>button.style.cssText='min-width:88px;padding:10px 16px;border:1px solid #ccd7e4;border-radius:8px;background:#fff;font-weight:800;cursor:pointer');overlay.querySelector('[data-ok]').style.cssText+=';border:0;background:#2563eb;color:#fff';overlay.querySelector('[data-cancel]').onclick=()=>overlay.remove();overlay.querySelector('[data-ok]').onclick=async()=>{const reason=overlay.querySelector('textarea')?.value.trim()||'';if(needsReason&&!reason){overlay.querySelector('[data-error]').textContent='반려 사유를 입력해 주세요.';return}await onConfirm(reason,overlay)};document.body.append(overlay)}async function decide(id,action,reason,overlay){const response=await fetch('/app/api/manager/requests/'+id+'/decision',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,reason})}),result=await response.json();overlay.remove();dialog('처리 결과',result.message||'처리되었습니다.',async(_reason,resultOverlay)=>{resultOverlay.remove();location.reload()})}document.addEventListener('click',async event=>{const row=event.target.closest?.('[data-manager-id]');if(!row)return;const id=row.dataset.managerId,response=await fetch('/app/api/manager/requests/'+id+'/review',{method:'POST'}),result=await response.json();if(!response.ok)return;const detail=document.getElementById('managerDetail');detail.querySelector('[data-manager-actions]')?.remove();if(result.status!=='manager_review')return;const actions=document.createElement('div');actions.dataset.managerActions='1';actions.style.cssText='display:flex;justify-content:center;gap:8px;margin-top:18px';actions.innerHTML='<button data-approve type="button">비서실 이관</button><button data-reject type="button">반려</button>';actions.querySelectorAll('button').forEach(button=>button.style.cssText='padding:10px 16px;border:1px solid #ccd7e4;border-radius:8px;background:#fff;font-weight:800;cursor:pointer');actions.querySelector('[data-approve]').style.cssText+=';border:0;background:#2563eb;color:#fff';actions.querySelector('[data-reject]').style.cssText+=';border-color:#e5484d;color:#c73535';actions.querySelector('[data-approve]').onclick=()=>dialog('비서실 이관','검토한 요청을 비서실로 이관하시겠습니까?',(_reason,overlay)=>decide(id,'approve','',overlay));actions.querySelector('[data-reject]').onclick=()=>dialog('요청 반려','요청자에게 돌려보낼 반려 사유를 입력해 주세요.',(reason,overlay)=>decide(id,'reject',reason,overlay),true);detail.append(actions)},false)});`;
}

